        private void by_date_check_CheckedChanged(object sender, EventArgs e)
        {
            if (by_date_check.Checked)
            {
                from_date_picker.Enabled = true;
                to_date_picker.Enabled = true;
            }
            else
            {
                from_date_picker.Enabled = false;
                to_date_picker.Enabled = false;
                from_date_picker.Text = null;
                to_date_picker.Text = null;
            }
        }

        private void by_store_check_CheckedChanged(object sender, EventArgs e)
        {
            if (by_store_check.Checked)
            {
                store_search_cmb.Enabled = true;
            }
            else
            {
                store_search_cmb.Enabled = false;
                store_search_cmb.Text = null;
            }
        }

        public void Search_By_Store()
        {
            sqlDataSource1.Queries.Remove(sqlDataSource1.Queries["Query"]);
            CustomSqlQuery query = new CustomSqlQuery();
            query.Sql = @"select stock_returns.date as 'Date',stock_returns.id as 'Code',stock_returns.name as 'Name',stores.id as 'Store.Code',stores.name as 'Store.Name',stores.area_code as 'Area.Code',stock_returns.fuel_expenses_amount as 'Fuel Exp',ac.name as 'Paid By' from (dbo.stock_returns stock_returns inner join dbo.stores stores on (stores.id = stock_returns.store_id)) left join accounts as ac on stock_returns.paid_by_ac_id=ac.id WHERE stock_returns.store_id='" + store_search_cmb.EditValue+"'  ORDER BY stock_returns.id DESC";
            query.Name = "Query";
            sqlDataSource1.Queries.Add(query);
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
        }
        public void Search_By_Store_And_Date()
        {
            sqlDataSource1.Queries.Remove(sqlDataSource1.Queries["Query"]);
            CustomSqlQuery query = new CustomSqlQuery();
            String end_date = Convert.ToDateTime(to_date_picker.Text).AddDays(1).ToString("dd-MM-yyyy");
            query.Sql = @"select stock_returns.date as 'Date',stock_returns.id as 'Code',stock_returns.name as 'Name',stores.id as 'Store.Code',stores.name as 'Store.Name',stores.area_code as 'Area.Code',stock_returns.fuel_expenses_amount as 'Fuel Exp',ac.name as 'Paid By' from (dbo.stock_returns stock_returns inner join dbo.stores stores on (stores.id = stock_returns.store_id)) left join accounts as ac on stock_returns.paid_by_ac_id=ac.id WHERE stock_returns.store_id='" + store_search_cmb.EditValue+"' and DATEADD(dd,0,DATEDIFF(dd,0,Convert(DATETIME,stock_returns.date,103))) >= DATEADD(dd,0,Convert(DATETIME,'"+from_date_picker.Text+"',103)) and DATEADD(dd,0,DATEDIFF(dd,0,Convert(DATETIME,stock_returns.date,103))) <= DATEADD(dd,0,Convert(DATETIME,'"+to_date_picker.Text+"',103)) ORDER BY stock_returns.id DESC";
            query.Name = "Query";
            sqlDataSource1.Queries.Add(query);
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
        }
        public void Search_By_Date()
        {
            sqlDataSource1.Queries.Remove(sqlDataSource1.Queries["Query"]);
            CustomSqlQuery query = new CustomSqlQuery();
            String end_date = Convert.ToDateTime(to_date_picker.Text).AddDays(1).ToString("dd-MM-yyyy");
            query.Sql = @"select stock_returns.date as 'Date',stock_returns.id as 'Code',stock_returns.name as 'Name',stores.id as 'Store.Code',stores.name as 'Store.Name',stores.area_code as 'Area.Code',stock_returns.fuel_expenses_amount as 'Fuel Exp',ac.name as 'Paid By' from (dbo.stock_returns stock_returns inner join dbo.stores stores on (stores.id = stock_returns.store_id)) left join accounts as ac on stock_returns.paid_by_ac_id=ac.id WHERE DATEADD(dd,0,DATEDIFF(dd,0,Convert(DATETIME,stock_returns.date,103))) >= DATEADD(dd,0,Convert(DATETIME,'" + from_date_picker.Text + "',103)) and DATEADD(dd,0,DATEDIFF(dd,0,Convert(DATETIME,stock_returns.date,103))) <= DATEADD(dd,0,Convert(DATETIME,'" + to_date_picker.Text + "',103)) ORDER BY stock_returns.id DESC";
            query.Name = "Query";
            sqlDataSource1.Queries.Add(query);
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
        }
        private void search_btn_Click(object sender, EventArgs e)
        {
            if(by_store_check.CheckState==CheckState.Checked && by_date_check.CheckState != CheckState.Checked)
            {
                if(store_search_cmb.Text == "")
                {
                    XtraMessageBox.Show("Please select store !");
                    store_search_cmb.ShowPopup();
                }
                else
                {
                    Search_By_Store();
                }
            }else if (by_store_check.CheckState == CheckState.Checked && by_date_check.CheckState == CheckState.Checked)
            {
                if (store_search_cmb.Text == "" && from_date_picker.Text =="" && to_date_picker.Text == "")
                {
                    XtraMessageBox.Show("please select store first then from date and to date !");
                    store_search_cmb.ShowPopup();
                }else if(store_search_cmb.Text == "")
                {
                    XtraMessageBox.Show("please select store !");
                    store_search_cmb.ShowPopup();
                }
                else if(from_date_picker.Text == "" && to_date_picker.Text == "")
                {
                    XtraMessageBox.Show("Please select from date and to date !");
                    from_date_picker.ShowPopup();
                }
                else if(from_date_picker.Text == "" )
                {
                    XtraMessageBox.Show("Please select from date !");
                    from_date_picker.ShowPopup();
                }else if(to_date_picker.Text == "")
                {
                    XtraMessageBox.Show("Please select to date !");
                    to_date_picker.ShowPopup();
                }
                else
                {
                    Search_By_Store_And_Date();
                }
            }
            else if (by_store_check.CheckState != CheckState.Checked && by_date_check.CheckState == CheckState.Checked)
            {
                if (from_date_picker.Text == "" && to_date_picker.Text == "")
                {
                    XtraMessageBox.Show("Please select from date and to date !");
                    from_date_picker.ShowPopup();
                }
                else if (from_date_picker.Text == "")
                {
                    XtraMessageBox.Show("Please select from date !");
                    from_date_picker.ShowPopup();
                }
                else if (to_date_picker.Text == "")
                {
                    XtraMessageBox.Show("Please select to date !");
                    to_date_picker.ShowPopup();
                }
                else
                {
                    Search_By_Date();
                }
            }
        }

        private void refresh_btn_Click(object sender, EventArgs e)
        {
            by_date_check.Checked = false;
            by_store_check.Checked = false;
            store_search_cmb.Text = null;
            from_date_picker.Text = null;
            to_date_picker.Text = null;
            store_search_cmb.Enabled = false;
            from_date_picker.Enabled = false;
            to_date_picker.Enabled = false;
            sqlDataSource1.Queries.Remove(sqlDataSource1.Queries["Query"]);
            CustomSqlQuery query = new CustomSqlQuery();
            query.Sql = @"select TOP 1000 stock_returns.date as 'Date',stock_returns.id as 'Code',stock_returns.name as 'Name',stores.id as 'Store.Code',stores.name as 'Store.Name',stores.area_code as 'Area.Code',stock_returns.fuel_expenses_amount as 'Fuel Exp',ac.name as 'Paid By' from (dbo.stock_returns stock_returns inner join dbo.stores stores on (stores.id = stock_returns.store_id)) left join accounts as ac on stock_returns.paid_by_ac_id=ac.id";
            query.Name = "Query";
            sqlDataSource1.Queries.Add(query);
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Stock_Returned stock_return = new Stock_Returned();
                stock_return.Stock_Return_Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns["Code"]));
                stock_return.Store_Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns["Store.Code"]));
                stock_return.DATE= Convert.ToDateTime(gridView1.GetFocusedRowCellValue(gridView1.Columns["Date"]));
                stock_return.Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Name"]));
                stock_return.Store_Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Store.Name"]));
                Stock_Return_Details stock_returned_details = new Stock_Return_Details(stock_return);
                stock_returned_details.Show(this);
            }
        }

        private void Stock_Return_History_SizeChanged(object sender, EventArgs e)
